function renderSavedCourses(){var s=requireLogin("student");if(!s)return;var box=document.getElementById("saved-courses-container");if(!box)return;var codes=getSavedCourses(s.username),courses=getAllCourses(),html="";for(var i=0;i<codes.length;i++){for(var j=0;j<courses.length;j++){if(courses[j].code.toLowerCase()===codes[i].toLowerCase()){var c=courses[j];html+='<div class="course-card"><div class="course-thumb"><span class="code-tag">'+escCourse(c.code)+'</span><span class="course-level">'+escCourse(c.level)+'</span><i class="'+escCourse(c.icon)+'"></i></div><div class="course-body"><h3>'+escCourse(c.name)+'</h3><div class="course-meta"><span>'+escCourse(c.duration)+'</span><span>'+escCourse(c.instructor)+'</span></div><p class="desc">'+escCourse(c.desc)+'</p><div style="display:flex;gap:8px"><a class="btn btn-primary btn-sm" href="/enroll-placeholder?course='+encodeURIComponent(c.code)+'">View Course</a><button class="btn btn-ghost btn-sm remove-saved" data-code="'+escCourse(c.code)+'">Remove</button></div></div></div>';}}}box.innerHTML=html||'<div class="placeholder-box" style="grid-column:1/-1">No saved courses yet. Use the bookmark icon in the course catalog to save one.</div>';var bs=box.querySelectorAll(".remove-saved");for(var k=0;k<bs.length;k++)bs[k].addEventListener("click",function(){toggleSavedCourse(s.username,this.getAttribute("data-code"));renderSavedCourses();});}document.addEventListener("DOMContentLoaded",renderSavedCourses);